INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(7301, '1 Samuel 22:21', '1 Samuel', 22, 21, '&nbsp;هغۀ داؤد ته ووئيل، چې ساؤل د مالِک خُدائ اِمامان څنګه ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7302, '1 Samuel 22:22', '1 Samuel', 22, 22, '&nbsp;داؤد هغۀ ته وفرمائيل، ”کله چې ما دوئيګ په هغه ورځ هلته وليدو، ما ته پته وه چې هغه به خامخا ساؤل ته ووائى. نو په دې وجه زۀ ستا د ټولو خپلوانو د مرګ ذمه وار يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7303, '1 Samuel 22:23', '1 Samuel', 22, 23, '&nbsp;ما سره ايسار شه او يرېږه مه. ساؤل مونږ دواړه وژل غواړى، خو تۀ به ما سره په امن کښې يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7304, '1 Samuel 23:1', '1 Samuel', 23, 1, '&nbsp;يوه ورځ داؤد واورېدل چې فلستيان د قعيله په ښار باندې حمله کوى او د درمند نه رېبلے شوے فصل پټوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7305, '1 Samuel 23:2', '1 Samuel', 23, 2, '&nbsp;نو هغۀ د مالِک خُدائ نه تپوس وکړو، ”زۀ لاړ شم څۀ چې په دې فلستيانو باندې حمله وکړم؟“ مالِک خُدائ ورته وفرمائيل، ”آو، په هغوئ حمله وکړه او قعيله بچ کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7306, '1 Samuel 23:3', '1 Samuel', 23, 3, '&nbsp;خو د داؤد سړو هغۀ ته وفرمائيل، ”کۀ مونږ دلته په يهوداه کښې يريږو، نو دا به زمونږ دپاره نوره هم سخته شى چې قعيله ته لاړ شُو او د فلستيانو په لښکر باندې حمله وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7307, '1 Samuel 23:4', '1 Samuel', 23, 4, '&nbsp;نو داؤد د مالِک خُدائ سره بيا خبره وکړه او مالِک خُدائ ورته وفرمائيل، ”قعيله ته ورشه، ځکه چې زۀ به تا له په فلستيانو باندې فتح درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7308, '1 Samuel 23:5', '1 Samuel', 23, 5, '&nbsp;نو داؤد او د هغۀ سړى قعيله ته لاړل او په فلستيانو يې حمله وکړه، هغوئ ډېر زيات کسان ووژل او د هغوئ څاروى يې بوتلل. نو داسې داؤد هغه ښار بچ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7309, '1 Samuel 23:6', '1 Samuel', 23, 6, '&nbsp;کله چې د اخيمُلک زوئ ابياتار وتښتېدو او په قعيله کښې د داؤد سره مِلاو شو، نو هغۀ د ځان سره پېش بند يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7310, '1 Samuel 23:7', '1 Samuel', 23, 7, '&nbsp;ساؤل خبر شو چې داؤد قعيلې ته تلے دے، نو ساؤل ووئيل، ”خُدائ پاک هغه ما له په لاس کښې راکړے دے. داؤد ځان په خپله ګېر کړو چې هغه يو داسې ښار ته لاړو چې پخې دروازې لرى او تالا کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7311, '1 Samuel 23:8', '1 Samuel', 23, 8, '&nbsp;نو ساؤل خپل لښکر د جنګ دپاره راوغوښتو، چې قعيلې ته لاړ شى او داؤد او د هغۀ لښکر ګېر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7312, '1 Samuel 23:9', '1 Samuel', 23, 9, '&nbsp;کله چې داؤد خبر شو چې ساؤل ورباندې د حملې کولو منصوبه جوړوى، نو هغۀ ابياتار اِمام ته وفرمائيل، ”پېش بند دلته راوړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7313, '1 Samuel 23:10', '1 Samuel', 23, 10, '&nbsp;بيا داؤد وفرمائيل، ”مالِکه خُدايه، د بنى اِسرائيلو خُدايه پاکه، ما دا اورېدلى دى چې ساؤل زما يعنې ستا د خِدمت کوونکى په وجه قعيلې ته د راتلو او د دې د ورانېدو منصوبه جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7314, '1 Samuel 23:11', '1 Samuel', 23, 11, '&nbsp;د قعيلې اوسېدونکى به ما ساؤل له په لاس کښې ورکړى څۀ؟ ساؤل به په رښتيا راشى څۀ لکه چې ما اورېدلى دى؟ مالِکه خُدايه، د بنى اِسرائيلو خُدايه پاکه، زۀ تا ته سوال کوم او ما له جواب راکړه.“ مالِک خُدائ ورته وفرمائيل، ”آو، ساؤل به راځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7315, '1 Samuel 23:12', '1 Samuel', 23, 12, '&nbsp;داؤد بيا تپوس وکړو، ”د قعيلې اوسېدونکى به ما او زما سړى ساؤل له په لاس کښې ورکوى څۀ؟“ مالِک خُدائ ورته وفرمائيل، ”آو، هغوئ به تاسو ورته حواله کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7316, '1 Samuel 23:13', '1 Samuel', 23, 13, '&nbsp;نو داؤد او د هغۀ سړى چې تقريباً ټول شپږ سوه وُو د قعيلې نه سمدستى لاړل او د يو ځائ نه بل ځائ ته تلل. کله چې ساؤل خبر شو چې داؤد د قعيلې نه تښتېدلے دے، نو هغۀ خپله منصوبه پرېښوده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7317, '1 Samuel 23:14', '1 Samuel', 23, 14, '&nbsp;داؤد د زيف سره نزدې په صحرا کښې، د غرونو په مُلک کښې په محفوظ ځائ کښې ايسار شو. ساؤل به هر وخت هغه لټولو، خو خُدائ پاک داؤد هغۀ له په لاس نۀ ورکولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7318, '1 Samuel 23:15', '1 Samuel', 23, 15, '&nbsp;کله چې داؤد د زيفه سره نزدې په صحرا کښې، په حورِش کښې وو نو پته ورته ولګېده چې ساؤل د هغۀ په مرګ پسې راوتلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7319, '1 Samuel 23:16', '1 Samuel', 23, 16, '&nbsp;يونتن هغۀ له هلته ورَغلو او داؤد يې زړَور کړو چې خُدائ پاک ستا مل دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7320, '1 Samuel 23:17', '1 Samuel', 23, 17, '&nbsp;او ورته يې ووئيل، ”مۀ يرېږه، زما پلار ساؤل تا ته نقصان نۀ شى دررسولے. هغۀ ته ډېره ښۀ پته ده چې تۀ به د بنى اِسرائيلو بادشاه يې او زۀ به په تا پسې دوېم کس يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7321, '1 Samuel 23:18', '1 Samuel', 23, 18, '&nbsp;هغوئ دواړو د يو بل سره د مالِک خُدائ په نوم باندې تړون وکړو. داؤد په حورِش کښې ايسار شو او يونتن خپل کور ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7322, '1 Samuel 23:19', '1 Samuel', 23, 19, '&nbsp;د زيف څۀ خلق په جبعه کښې ساؤل له لاړل او ورته يې ووئيل، ”داؤد زمونږ په علاقه حورِش کښې د حکيله په غرۀ باندې پټ دے، چې دا د يشيمون صحرا جنوبى حِصه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7323, '1 Samuel 23:20', '1 Samuel', 23, 20, '&nbsp;بادشاه سلامت، مونږ ته پته ده چې تۀ هغه نيول غواړې، نو زمونږ علاقې ته راشه او مونږ به يې ونيسو او تا ته به يې حواله کړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7324, '1 Samuel 23:21', '1 Samuel', 23, 21, '&nbsp;ساؤل ورته ووئيل، ”مالِک خُدائ دې تاسو له برکت درکړى ځکه چې تاسو په ما ډېر مِهربانه يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7325, '1 Samuel 23:22', '1 Samuel', 23, 22, '&nbsp;لاړ شئ او يو ځل يې بيا وګورئ، دا خبره صفا کړئ چې هغه چرته دے او هغه هلته چا ليدلے دے. ما اورېدلى دى چې هغه ډېر چالاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7326, '1 Samuel 23:23', '1 Samuel', 23, 23, '&nbsp;بلکل هم هغه ځايونه ولټوئ چرته چې هغه پټ دے او خامخا سيدها ما له واپس خبر راوړئ. بيا به زۀ ستاسو سره لاړ شم او کۀ هغه تر اوسه پورې په هغه علاقه کښې وى، نو هغه به زۀ رانيسم، تر دې پورې چې د يهوداه ټول مُلک به ورپسې لټوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7327, '1 Samuel 23:24', '1 Samuel', 23, 24, '&nbsp;نو هغوئ روان شول او د ساؤل نه مخکښې زيف ته واپس راورسېدل. داؤد او د هغۀ سړى د معون په صحرا کښې وُو، چې د يشيمون صحرا په جنوبى حِصه کښې خُشک مېدان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7328, '1 Samuel 23:25', '1 Samuel', 23, 25, '&nbsp;ساؤل او د هغۀ سړى د داؤد لټولو دپاره روان شول، خو هغه د دې نه خبر شو او د معون په صحرا کښې د ګټو يو غر ته لاړل او هلته ايسار شو. کله چې ساؤل د دې نه خبر شو نو هغه په داؤد پسې لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7329, '1 Samuel 23:26', '1 Samuel', 23, 26, '&nbsp;ساؤل او د هغۀ سړى د غرۀ په يو طرف باندې وُو او داؤد او د هغۀ سړى د غرۀ په بل طرف باندې وُو. داؤد تېزى کوله چې د ساؤل نه لرې شى، خو ساؤل دومره ورنزدې شو چې داؤد او د هغۀ لښکر يې نيولے هم شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7330, '1 Samuel 23:27', '1 Samuel', 23, 27, '&nbsp;نو هم په هغه وخت يو پېغام وړونکے راورسېدو او ساؤل ته يې ووئيل، ”فوراً راواپس شه. فلستيان په مُلک حمله کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7331, '1 Samuel 23:28', '1 Samuel', 23, 28, '&nbsp;نو ساؤل په داؤد پسې نور لا نۀ ړو او د فلستيانو سره جنګ کولو دپاره لاړو. نو دا ځکه د هغه ځائ نوم د تښتېدو ګټ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7332, '1 Samuel 23:29', '1 Samuel', 23, 29, '&nbsp;داؤد روان شو او د عين‌جدى علاقې ته لاړو، هلته په محفوظ ځايونو کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7333, '1 Samuel 24:1', '1 Samuel', 24, 1, '&nbsp;کله چې ساؤل د فلستيانو سره جنګ کولو نه راواپس شو، نو هغه خبر شو چې داؤد د عين‌جدى په صحرا کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7334, '1 Samuel 24:2', '1 Samuel', 24, 2, '&nbsp;ساؤل د بنى اِسرائيلو نه درې زره تکړه فوجيان ځان سره کړل او د ځنګلى چېلۍ ګټو نمرخاتۀ طرف ته په داؤد او د هغۀ په سړو پسې روان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7335, '1 Samuel 24:3', '1 Samuel', 24, 3, '&nbsp;هغه د لارې په غاړه د ګډو شپول سره نزدې يو غار ته راغلو او اودس يې مات کړو. داسې هم په هغه غار کښې وشول چې په کوم غار کښې داؤد او د هغۀ سړى شاته حِصه کښې پټ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7336, '1 Samuel 24:4', '1 Samuel', 24, 4, '&nbsp;د داؤد سړو غلى شان هغۀ ته وفرمائيل، ”دا ستا دپاره يوه موقع ده. مالِک خُدائ تا ته فرمائيلى دى چې هغه به تا له ستا دشمن په لاس کښې درکړى او چې بيا دې څۀ خوښه وى نو هغه ورسره کولے شې.“ داؤد غلے لاړو او د ساؤل د چُوغې نه يې يوه ټُکړه پرې کړه خو ساؤل ته د دې پته ونۀ لګېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7337, '1 Samuel 24:5', '1 Samuel', 24, 5, '&nbsp;خو خپل ضمير داؤد ملامته کړو ځکه چې هغۀ د ساؤل د چُوغې نه يوه ټُکړه پرې کړې وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7338, '1 Samuel 24:6', '1 Samuel', 24, 6, '&nbsp;او هغۀ خپلو سړو ته وفرمائيل، ”مالِک خُدائ دې ما د دې نه وساتى چې زۀ خپل نېک ته څۀ نقصان ورسوم، کوم چې مالِک خُدائ خوښ کړے دے. زۀ خو به هغۀ ته نقصان نۀ رسوم، ځکه چې هغه بادشاه دے او مالِک خُدائ هغه خوښ کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7339, '1 Samuel 24:7', '1 Samuel', 24, 7, '&nbsp;نو داؤد خپل سړى دې ته راضى کړل چې هغوئ به په ساؤل حمله نۀ کوى. ساؤل پاڅېدو، د غرۀ نه روان شو او په خپله مخه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7340, '1 Samuel 24:8', '1 Samuel', 24, 8, '&nbsp;نو داؤد ورپسې لاړو او آواز يې ورته وکړو، ”بادشاه سلامت.“ ساؤل راوګرځېدو او داؤد د عزت نه زمکې ته ټيټ شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7341, '1 Samuel 24:9', '1 Samuel', 24, 9, '&nbsp;او وې فرمائيل، ”تۀ هغه خلقو ته غوږ ولې نيسې چې کوم وائى چې زۀ تا ته د نقصان رسولو کوشش کوم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7342, '1 Samuel 24:10', '1 Samuel', 24, 10, '&nbsp;تا په خپله وليدل چې مالِک خُدائ تۀ اوس اوس په دې غار کښې ما له په لاس کښې راکړې. زما څۀ سړو ما ته ووئيل چې زۀ تا ووژنم، خو ما درته د رحم په نظر وکتل او ومې وئيل چې زۀ خو به تا ته نقصان نۀ رسوم، ځکه چې تۀ هغه څوک يې چې مالِک خُدائ بادشاه خوښ کړے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7343, '1 Samuel 24:11', '1 Samuel', 24, 11, '&nbsp;وګوره زما پلاره، د خپلې چُوغې ټُکړه وګوره چې زما په لاس کښې ده. ما تۀ وژلے شوې، خو صِرف ما دا ټُکړه پرې کړه. په کار دى چې تۀ دا ومنې چې ما ستا خِلاف د بغاوت يا تا ته د نقصان رسولو خيال هم نۀ دے کړے. او تۀ ما د وژلو دپاره نيسې، اګر چې ما درسره هيڅ بد نۀ دى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7344, '1 Samuel 24:12', '1 Samuel', 24, 12, '&nbsp;مالِک خُدائ دې اِنصاف وکړى چې په مونږ کښې څوک په غلطه دے. زما خِلاف دې چې کوم کار کړے وى نو مالِک خُدائ دې د هغې سزا درکړى، خو زۀ به تا ته هيڅ نقصان نۀ رسوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7345, '1 Samuel 24:13', '1 Samuel', 24, 13, '&nbsp;لکه د مشرانو د خولو خبره ده، ”د بدعملو هر کار بد وى.“ خو زۀ به تا ته نقصان نۀ رسوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7346, '1 Samuel 24:14', '1 Samuel', 24, 14, '&nbsp;ګوره، د بنى اِسرائيلو بادشاه د چا د وژلو کوشش کوى؟ ګوره، هغه په چا پسې شوے دے؟ په يو مړ سپى پسې، په يوې ورَږې پسې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7347, '1 Samuel 24:15', '1 Samuel', 24, 15, '&nbsp;مالِک خُدائ به اِنصاف وکړى او هغه به فېصله وکړى چې په مونږ کښې څوک په غلطه دے. هغه دې مسئلې ته وګورى، زما حِفاظت دې وکړى او ما دې ستا د لاس نه بچ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7348, '1 Samuel 24:16', '1 Samuel', 24, 16, '&nbsp;کله چې داؤد خبرې ختمې کړې، نو ساؤل ووئيل، ”دا تۀ يې داؤده، زما زويه؟“ او هغه په ژړا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7349, '1 Samuel 24:17', '1 Samuel', 24, 17, '&nbsp;بيا هغۀ داؤد ته وفرمائيل، ”تۀ په حقه يې او زۀ په ناحقه يم. تۀ ما سره ډېر ښۀ يې، اګر چې ما تا سره ډېر بد کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7350, '1 Samuel 24:18', '1 Samuel', 24, 18, '&nbsp;تا نن ما ته وښودل چې تۀ ما سره څومره ښۀ يې، ځکه چې تا زۀ ونۀ وژلم، تر دې پورې چې مالِک خُدائ زۀ تا له په لاس کښې درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7351, '1 Samuel 24:19', '1 Samuel', 24, 19, '&nbsp;يو سړے څو ځلې خپل دشمن نيسى او بيا يې د نقصان رسولو نه بغېر پرېږدى؟ تا چې نن ما سره څۀ کړى دى مالِک خُدائ دې تا له د هغې اجر درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7352, '1 Samuel 24:20', '1 Samuel', 24, 20, '&nbsp;نو زما يقين دے چې تۀ به د اِسرائيل بادشاه يې او بادشاهى به ستا د اختيار لاندې قائمه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7353, '1 Samuel 24:21', '1 Samuel', 24, 21, '&nbsp;خو تۀ ما سره د مالِک خُدائ په نوم لوظ وکړه چې تۀ به زما اولاد ته هيڅ نقصان نۀ رسوې، نو داسې به زما او زما د خاندان نوم بېخى نۀ هېريږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7354, '1 Samuel 24:22', '1 Samuel', 24, 22, '&nbsp;نو داؤد د ساؤل سره هغه لوظ وکړو. نو ساؤل واپس کور ته لاړو او داؤد او د هغۀ سړى محفوظو ځايونو ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7355, '1 Samuel 25:1', '1 Samuel', 25, 1, '&nbsp;نو سموئيل مړ شو او ټول بنى اِسرائيليان راغونډ شول او په هغۀ يې د غم ژړا وکړه. بيا هغوئ هغه په راما کښې په خپل خاندانى قبر کښې ښخ کړو. حضرت داؤد او ابى‌جيل د هغې نه پس، داؤد د فاران صحرا ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7356, '1 Samuel 25:4', '1 Samuel', 25, 4, '&nbsp;او داؤد، څوک چې په صحرا کښې وو د دې نه خبر شو چې نابال د خپلو ګډو نه وړۍ کلولې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7357, '1 Samuel 25:5', '1 Samuel', 25, 5, '&nbsp;نو هغۀ لس زلمى د دې حُکم سره ولېږل چې کرمل ته لاړ شئ، نابال ولټوئ او زما سلام ورورسوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7358, '1 Samuel 25:6', '1 Samuel', 25, 6, '&nbsp;هغۀ ته ووايئ، ”خوشحاله او ژوندے اوسې، په تا او ستا په کور دې سلامتى وى او په هغه هر څۀ دې سلامتى وى چې تۀ يې لرې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7359, '1 Samuel 25:7', '1 Samuel', 25, 7, '&nbsp;هغۀ اورېدلى دى چې تۀ د خپلو ګډو وړۍ کلوې او هغۀ غوښتل چې تا ته دا پته ولګى چې کله ستا شپانۀ مونږ سره وُو نو مونږ هغوئ ته څۀ نقصان نۀ دے رسولے. کله چې هغوئ په کرمل کښې وُو نو هيڅکله د هغوئ يو څيز هم نۀ دے پټ کړے شوے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7360, '1 Samuel 25:8', '1 Samuel', 25, 8, '&nbsp;تۀ د خپلو سړو نه تپوس وکړه او هغوئ به تا ته هم دغه شان ووائى. نو تۀ به مونږ سره ښېګړه وکړې څۀ، ځکه چې مونږ د اختر په ورځ راغلى يُو؟ تۀ مونږ يعنې ستا خِدمت کوونکو او خپل دوست داؤد له څۀ راکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7361, '1 Samuel 25:9', '1 Samuel', 25, 9, '&nbsp;د داؤد زلمى راورسېدل او د داؤد دا پېغام يې نابال له ورکړو. او هغوئ هلته اِنتظار وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7362, '1 Samuel 25:10', '1 Samuel', 25, 10, '&nbsp;او آخر نابال جواب ورکړو چې، ”داؤد څوک دے؟ د يَسى زوئ څوک دے؟ نن سبا ډېر نوکران د خپلو نېکانو نه تښتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7363, '1 Samuel 25:11', '1 Samuel', 25, 11, '&nbsp;زۀ روټۍ، اوبۀ او هغه ځناور ولې يوسم چې ما د خپلو نوکرانو دپاره حلال کړى دى چې هغه سړو له يې ورکړم چې ما ته پته هم نشته چې هغوئ د کوم ځائ نه راغلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7364, '1 Samuel 25:12', '1 Samuel', 25, 12, '&nbsp;د داؤد سړى واپس راغلل او چې نابال څۀ وئيلى وُو نو هغه يې ورته ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7365, '1 Samuel 25:13', '1 Samuel', 25, 13, '&nbsp;داؤد خپلو سړو ته وفرمائيل، ”هر يو سړے خپلې تُورې وتړئ.“ هغۀ حُکم ورکړو او هغوئ ټولو تُورې وتړلې. داؤد په خپله هم تُوره وتړله او تقريباً د خپلو څلورو سوو سړو سره لاړو، چې دوه سوه سړى يې وروستو د سامان سره پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7366, '1 Samuel 25:14', '1 Samuel', 25, 14, '&nbsp;د نابال يو نوکر د نابال ښځې ابى‌جيل ته ووئيل، ”تۀ خبر يې؟ داؤد د صحرا نه پېغام وړُونکى رالېږلى دى چې زمونږ نېک ته سلام ووائى، خو هغۀ يې بې‌عزتى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7367, '1 Samuel 25:15', '1 Samuel', 25, 15, '&nbsp;خو هغوئ زمونږ سره ډېر ښۀ وُو، هغوئ مونږ کله هم نۀ يُو تنګ کړى او مونږ به هر وخت د هغوئ سره په پټو کښې وُو او زمونږ يو څيز هم نۀ دے پټ کړے شوے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7368, '1 Samuel 25:16', '1 Samuel', 25, 16, '&nbsp;هغوئ شپه او ورځ زمونږ حِفاظت کولو او چې کله هم مونږ د هغوئ سره وُو نو هغوئ زمونږ د رَمو حِفاظت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7369, '1 Samuel 25:17', '1 Samuel', 25, 17, '&nbsp;دا زمونږ د نېک او د هغۀ د مکمل خاندان دپاره د تباهۍ سبب جوړېدے شى. هغه دومره بداخلاقه سړے دے چې د هيچا خبره به هم نۀ اورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7370, '1 Samuel 25:18', '1 Samuel', 25, 18, '&nbsp;ابى‌جيل زر زر دوه سوه روټۍ راټولې کړې، دوه د ميو نه ډکې مشکيزې، پينځۀ حلال شوى ګډان او لس کلو وريتې دانې، سل د کشمشو موټى او دوه سوه موټى د اوچو اينځرو يې واخستل او په خرونو يې بار کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7371, '1 Samuel 25:19', '1 Samuel', 25, 19, '&nbsp;بيا هغې نوکرانو ته ووئيل، ”تاسو مخکښې ځئ او زۀ به په تاسو پسې درځم.“ خو هغې خپل خاوند ته هيڅ هم ونۀ وئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7372, '1 Samuel 25:20', '1 Samuel', 25, 20, '&nbsp;هغې خپل خر د غرۀ په لمن کښې په تاو راتاو لاره باندې روان کړے وو چې ناڅاپه هغه د داؤد او د هغۀ د سړو سره مِلاو شوه چې د هغې طرف ته راروان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7373, '1 Samuel 25:21', '1 Samuel', 25, 21, '&nbsp;داؤد دا سوچ کولو چې، ”ما په دې صحرا کښې د دې کس د جائيداد حِفاظت ولې وکړو؟ د هغۀ يو څيز مې هم ورکېدلو ته نۀ دے پرېښے او چې ما د هغۀ سره کوم مدد کړے دے نو د هغې بدله داسې راکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7374, '1 Samuel 25:22', '1 Samuel', 25, 22, '&nbsp;خُدائ پاک دې ما ووژنى کۀ ما هغه ټول سړى د سحر نه مخکښې ونۀ وژل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7375, '1 Samuel 25:23', '1 Samuel', 25, 23, '&nbsp;کله چې ابى‌جيل داؤد وليدو، نو هغه زر زر راکوزه شوه او خپل ځان يې په زمکه وغورزولو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7376, '1 Samuel 25:24', '1 Samuel', 25, 24, '&nbsp;او د داؤد په پښو کښې پرېوته او هغۀ ته يې ووئيل، ”يواځې ما قصورواره وګڼه، خپلې وينځې له د خبرو کولو اجازت ورکړه او چې ستا وينځه څۀ وئيل غواړى نو صاحِبه، هغې ته غوږ ونيسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7377, '1 Samuel 25:25', '1 Samuel', 25, 25, '&nbsp;صاحِبه، د دې بې‌کاره سړى نابال خبره مۀ اوره. هغه په رښتيا هم هغه شے دے لکه چې څنګه يې نامه ده، کم عقل. صاحِبه، کله چې ستا نوکران راورسېدل نو زۀ هلته نۀ وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7378, '1 Samuel 25:26', '1 Samuel', 25, 26, '&nbsp;دا مالِک خُدائ وو چې هغۀ د بدل اخستلو نه او تۀ يې د خپلو دشمنانو د وژلو نه ساتلے يې. او اوس زۀ تا ته په ژوندى مالِک خُدائ قسم خورم چې ستا دشمنان او هر څوک چې تا ته نقصان رسوى هغوئ له به د نابال په شان سزا ورکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7379, '1 Samuel 25:27', '1 Samuel', 25, 27, '&nbsp;نو اوس، چې ستا وينځې کومه تُحفه تا له راوړې ده هغه قبوله کړه او خپلو زلمو له يې ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7380, '1 Samuel 25:28', '1 Samuel', 25, 28, '&nbsp;صاحِبه، کۀ ما څۀ قصور کړے وى نو ما معاف کړه. مالِک خُدائ به ستا او ستا د بچو بادشاهى قائمه ساتى، ځکه چې زما نېک د مالِک خُدائ دپاره جنګونه کوى، او چې تر کومې پورې تۀ ژوندے يې نو تۀ دې بد عمل ونۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7381, '1 Samuel 25:29', '1 Samuel', 25, 29, '&nbsp;کۀ څوک په تا باندې حمله کوى او ستا د وژلو کوشش کوى، نو مالِک خُدائ ستا خُدائ پاک به تا داسې بچ ساتى لکه چې څوک د قيمتى خزانې حِفاظت کوى. او هغه به ستا دشمنان داسې وغورزوى لکه چې څوک په لينده کښې کاڼے لړه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7382, '1 Samuel 25:30', '1 Samuel', 25, 30, '&nbsp;او کله چې مالِک خُدائ هغه ټول ښۀ کارونه کړى وى لکه څنګه يې چې تا سره وعده کړې ده او تۀ يې د بنى اِسرائيلو مشر جوړ کړے يې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7383, '1 Samuel 25:31', '1 Samuel', 25, 31, '&nbsp;نو صاحِبه، تۀ به پښېمانه نۀ يې او نۀ به په زړۀ کښې خفه يې، چې بغېر د څۀ وجې نه دې خلق وژلى وى يا دې خپله بدله اخستې وى. او کله چې مالِک خُدائ برکت درکړى، نو مِهربانى وکړه چې خپله خِدمت کوونکې هېره نۀ کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7384, '1 Samuel 25:32', '1 Samuel', 25, 32, '&nbsp;داؤد ابى‌جيل ته وفرمائيل، ”د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک صِفت دې وى چې هغۀ نن تۀ زما سره مِلاوېدو له راولېږلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7385, '1 Samuel 25:33', '1 Samuel', 25, 33, '&nbsp;ستا د هوښيارتوب دپاره دې د خُدائ پاک شُکر وى او د هغې دپاره چې تا نن وکړل چې د وينې تويولو د جرم او د خپل بدل اخستلو نه دې وساتلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7386, '1 Samuel 25:34', '1 Samuel', 25, 34, '&nbsp;مالِک خُدائ زۀ تا ته د نقصان رسولو نه ساتلے يم. خو زۀ د بنى اِسرائيلو په ژوندى خُدائ پاک قسم خورم کۀ تۀ ما سره مِلاوېدو له زر زر نۀ وې راغلې، نو د سحر پورې به د نابال ټول سړى مړۀ شوى وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7387, '1 Samuel 25:35', '1 Samuel', 25, 35, '&nbsp;بيا داؤد هغه څۀ قبول کړل چې هغې راوړى وُو او هغې ته يې وفرمائيل، ”په خېر سره واپس کور ته لاړه شه. ما ستا خبره اورېدلې ده او ستا عرض مې منلے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7388, '1 Samuel 25:36', '1 Samuel', 25, 36, '&nbsp;ابى‌جيل واپس نابال له لاړه، هغه په کور کښې وو او داسې روټۍ يې کړې وه چې د بادشاهانو سره سمون خورى. هغه په نشه کښې وو او ښۀ په سور کښې وو، نو هغې تر سحره پورې هغۀ ته هيڅ هم ونۀ وئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7389, '1 Samuel 25:37', '1 Samuel', 25, 37, '&nbsp;بيا کله چې د هغۀ نه نشه لاړه، نو هغې ورته هر څۀ ووئيل. هغه فالج ووهلو او مکمل شل شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7390, '1 Samuel 25:38', '1 Samuel', 25, 38, '&nbsp;تقريباً لس ورځې وروستو مالِک خُدائ نابال ووهلو او مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7391, '1 Samuel 25:39', '1 Samuel', 25, 39, '&nbsp;کله چې داؤد خبر شو چې نابال مړ شو، نو هغۀ وفرمائيل، ”د مالِک خُدائ ثناء صِفت دې وى. هغۀ د نابال نه زما د بې‌عزتۍ بدله اخستې ده او زۀ يعنې خپل خِدمت کوونکے يې د غلط کار نه ساتلے يم. مالِک خُدائ نابال له د هغۀ د بدعملۍ سزا ورکړې ده.“ بيا داؤد ابى‌جيل له خبر ورولېږلو چې زما سره وادۀ وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7392, '1 Samuel 25:40', '1 Samuel', 25, 40, '&nbsp;د هغۀ نوکران په کرمل کښې هغې له ورغلل او ورته يې ووئيل، ”داؤد مونږ رالېږلى يُو چې تا بوځُو او د هغۀ ښځه شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7393, '1 Samuel 25:41', '1 Samuel', 25, 41, '&nbsp;ابى‌جيل سر زمکې ته ټيټ کړو او وې وئيل، ”زۀ د هغۀ وينځه يم، زۀ د هغۀ د نوکرانو د پښو وينځلو دپاره تياره يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7394, '1 Samuel 25:42', '1 Samuel', 25, 42, '&nbsp;هغه زر زر پاڅېده او په خر سوره شوه. پينځۀ نوکرانې ورسره وې، هغه د داؤد د نوکرانو سره لاړه او د هغۀ ښځه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7395, '1 Samuel 25:43', '1 Samuel', 25, 43, '&nbsp;داؤد د يزرعيل اخينوعم هم وادۀ کړې وه او دواړه يې ښځې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7396, '1 Samuel 25:44', '1 Samuel', 25, 44, '&nbsp;په دې دوران کښې، د داؤد چې کومه ښځه وه او د ساؤل لور وه، ساؤل هغه د داؤد نه خلاصه کړه او د ليس زوئ فلطى له ورکړه. فلطى د جليم د ښار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7397, '1 Samuel 26:1', '1 Samuel', 26, 1, '&nbsp;بيا د زيف يو څو سړى په جبعه کښې ساؤل له راغلل او ورته يې ووئيل چې، ”داؤد د يشيمون صحرا په غاړه د حکيله په غرۀ باندې پټ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7398, '1 Samuel 26:2', '1 Samuel', 26, 2, '&nbsp;نو ساؤل سمدستى د درېو زرو ښو بنى اِسرائيلو فوجيانو سره د زيف صحرا ته لاړو چې داؤد ولټوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7399, '1 Samuel 26:3', '1 Samuel', 26, 3, '&nbsp;او د لارې په غاړه د حکيله په غرۀ باندې يې خېمې ولګولې. داؤد تر اوسه پورې په هغه صحرا کښې وو او کله چې هغه خبر شو چې ساؤل د هغۀ لټولو له راغلے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7400, '1 Samuel 26:4', '1 Samuel', 26, 4, '&nbsp;هغۀ جاسوسان ولېږل او دا يې معلوم کړل چې ساؤل په رښتيا هلته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');